-- Kanban - create the database schema from empty
-- Generated by `npm run db:sql` from Solution/backend-py/alembic/sql - do not edit by hand.
--
-- For a NEW, EMPTY database (no tables yet).
-- Ends at 0020_testing_to_uat. Run it ONCE, connected as the database OWNER role (the user in
-- DATABASE_OWNER_URL), e.g.  psql "<owner connection string>" -f <this file>
-- or paste it into pgAdmin / the Azure portal query editor. It is one transaction: any error
-- leaves the database untouched.
--
-- Table rights are granted to the runtime role "app_rw" (the user in DATABASE_URL). If yours
-- is different, regenerate with `npm run db:sql -- <role>` (or replace every "app_rw").
-- Both roles must exist first (CREATE ROLE ... LOGIN; Solution/db/init/001_roles_and_template.sql
-- or Solution/docs/azure-code-deploy.md section 2), or the GRANTs fail and nothing changes.
-- Afterwards start the new app as usual: it sees every migration recorded and changes nothing.

BEGIN;

-- ===== 0001_init =====
-- Migration bookkeeping (read by backend/src/db/migrate.ts).
CREATE TABLE IF NOT EXISTS schema_migration (
  id          text PRIMARY KEY,
  applied_at  timestamptz NOT NULL DEFAULT now()
);

INSERT INTO schema_migration (id) VALUES ('0001_init') ON CONFLICT DO NOTHING;

-- ===== 0002_identity =====
-- Starter identity: users, server-side sessions (ADR-005), per-user preferences.
-- ids are ULIDs (char(26), platform/ulid.ts). Session id = SHA-256 of the cookie value.
CREATE TABLE app_user (
  id          char(26)    PRIMARY KEY,
  email       text        NOT NULL,
  name        text        NOT NULL,
  role        text        NOT NULL DEFAULT 'member' CHECK (role IN ('member', 'admin')),
  status      text        NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  external_id text,                 -- Entra object id once SSO is on; null for dev/seeded users
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX app_user_email_idx ON app_user (lower(email));
CREATE UNIQUE INDEX app_user_external_idx ON app_user (external_id) WHERE external_id IS NOT NULL;

CREATE TABLE session (
  id          char(64)    PRIMARY KEY,   -- sha256 hex of the cookie value
  user_id     char(26)    NOT NULL REFERENCES app_user (id),
  created_at  timestamptz NOT NULL,
  expires_at  timestamptz NOT NULL,
  revoked_at  timestamptz
);
CREATE INDEX session_user_idx ON session (user_id);

CREATE TABLE user_preference (
  user_id     char(26)    PRIMARY KEY REFERENCES app_user (id),
  theme       text        NOT NULL DEFAULT 'system' CHECK (theme IN ('light', 'dark', 'system')),
  accent      text        NOT NULL DEFAULT 'linen',
  updated_at  timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE, DELETE ON app_user TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON user_preference TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON session TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0002_identity') ON CONFLICT DO NOTHING;

-- ===== 0003_cards =====
-- S1 cards: card, card_event (append-only), card_comment. See Outputs/Architecture/data-model.md.
CREATE OR REPLACE FUNCTION append_only_violation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'append_only_violation: % on % is not allowed', TG_OP, TG_TABLE_NAME
    USING ERRCODE = 'raise_exception';
END
$$;

CREATE SEQUENCE card_number_seq;

CREATE TABLE card (
  id            char(26)     PRIMARY KEY,
  number        integer      NOT NULL UNIQUE DEFAULT nextval('card_number_seq'),
  title         text         NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200),
  description   text         NOT NULL DEFAULT '' CHECK (char_length(description) <= 20000),
  plane         text         NOT NULL CHECK (plane IN ('private', 'org')),
  state         text         NOT NULL DEFAULT 'backlog'
                             CHECK (state IN ('backlog', 'in_prep', 'ready', 'in_development', 'testing', 'uat', 'delivered', 'cancelled')),
  owner_id      char(26)     NOT NULL REFERENCES app_user (id),
  assignee_id   char(26)     REFERENCES app_user (id),
  priority      smallint     NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 4),
  tags          text[]       NOT NULL DEFAULT '{}',
  eta           date,
  effort_hours  numeric(7,2) CHECK (effort_hours >= 0),
  closed_at     timestamptz,
  version       integer      NOT NULL DEFAULT 1,
  created_at    timestamptz  NOT NULL DEFAULT now(),
  updated_at    timestamptz  NOT NULL DEFAULT now()
);
CREATE INDEX card_owner_plane_state_idx ON card (owner_id, plane, state);
CREATE INDEX card_closed_idx ON card (closed_at) WHERE closed_at IS NOT NULL;

CREATE TABLE card_event (
  id          char(26)    PRIMARY KEY,
  card_id     char(26)    NOT NULL REFERENCES card (id),
  group_id    char(26)    NOT NULL,
  field       text        NOT NULL,
  old_value   jsonb,
  new_value   jsonb,
  actor_id    char(26)    NOT NULL REFERENCES app_user (id),
  created_at  timestamptz NOT NULL
);
CREATE INDEX card_event_card_idx ON card_event (card_id, created_at);
CREATE INDEX card_event_actor_idx ON card_event (actor_id, created_at);
CREATE TRIGGER card_event_append_only BEFORE UPDATE OR DELETE ON card_event
  FOR EACH ROW EXECUTE FUNCTION append_only_violation();

CREATE TABLE card_comment (
  id          char(26)    PRIMARY KEY,
  card_id     char(26)    NOT NULL REFERENCES card (id),
  author_id   char(26)    NOT NULL REFERENCES app_user (id),
  body        text        NOT NULL CHECK (char_length(body) BETWEEN 1 AND 10000),
  created_at  timestamptz NOT NULL,
  edited_at   timestamptz
);
CREATE INDEX card_comment_card_idx ON card_comment (card_id, created_at);

GRANT USAGE ON SEQUENCE card_number_seq TO app_rw;
GRANT SELECT, INSERT, UPDATE ON card TO app_rw;
GRANT SELECT, INSERT ON card_event TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON card_comment TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0003_cards') ON CONFLICT DO NOTHING;

-- ===== 0004_org =====
-- S2 org plane: team, team_member, program, project, card_link, org_event; card.team_id/project_id;
-- copied_from_card_id on card_event/card_comment (D-056). See Outputs/Architecture/data-model.md (S2).
CREATE TABLE team (
  id          char(26)    PRIMARY KEY,
  name        text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80),
  description text        NOT NULL DEFAULT '' CHECK (char_length(description) <= 2000),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX team_name_idx ON team (lower(name));

CREATE TABLE team_member (
  team_id   char(26)    NOT NULL REFERENCES team (id),
  user_id   char(26)    NOT NULL REFERENCES app_user (id),
  added_at  timestamptz NOT NULL,
  added_by  char(26)    NOT NULL REFERENCES app_user (id),
  PRIMARY KEY (team_id, user_id)
);
CREATE INDEX team_member_user_idx ON team_member (user_id);

CREATE TABLE program (
  id          char(26)    PRIMARY KEY,
  name        text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120),
  description text        NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
  target_date date,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX program_name_idx ON program (lower(name));

CREATE TABLE project (
  id          char(26)    PRIMARY KEY,
  name        text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120),
  description text        NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
  team_id     char(26)    NOT NULL REFERENCES team (id),
  program_id  char(26)    REFERENCES program (id),
  target_date date,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (id, team_id)                                  -- target of card's composite FK (FR-023)
);
CREATE UNIQUE INDEX project_team_name_idx ON project (team_id, lower(name));   -- D-045
CREATE INDEX project_program_idx ON project (program_id);

ALTER TABLE card
  ADD COLUMN team_id    char(26) REFERENCES team (id),
  ADD COLUMN project_id char(26),
  ADD CONSTRAINT card_private_has_no_team CHECK (plane = 'org' OR (team_id IS NULL AND project_id IS NULL)),
  -- A card's team is its project's team, by construction; re-teaming a project cascades (D-046).
  ADD CONSTRAINT card_project_team_fk FOREIGN KEY (project_id, team_id)
    REFERENCES project (id, team_id) ON UPDATE CASCADE;
CREATE INDEX card_team_state_idx ON card (team_id, state) WHERE plane = 'org';
CREATE INDEX card_project_idx ON card (project_id);
CREATE INDEX card_unassigned_idx ON card (state) WHERE plane = 'org' AND team_id IS NULL;

CREATE TABLE card_link (
  id            char(26)    PRIMARY KEY,
  from_card_id  char(26)    NOT NULL REFERENCES card (id),
  to_card_id    char(26)    NOT NULL REFERENCES card (id),
  type          text        NOT NULL CHECK (type IN ('relates_to', 'depends_on', 'blocks')),
  created_by    char(26)    NOT NULL REFERENCES app_user (id),
  created_at    timestamptz NOT NULL,
  CHECK (from_card_id <> to_card_id),
  UNIQUE (from_card_id, to_card_id, type)
);
CREATE INDEX card_link_from_idx ON card_link (from_card_id);
CREATE INDEX card_link_to_idx ON card_link (to_card_id);

CREATE TABLE org_event (
  id          char(26)    PRIMARY KEY,
  entity_type text        NOT NULL CHECK (entity_type IN ('team', 'program', 'project')),
  entity_id   char(26)    NOT NULL,
  group_id    char(26)    NOT NULL,
  field       text        NOT NULL,
  old_value   jsonb,
  new_value   jsonb,
  actor_id    char(26)    NOT NULL REFERENCES app_user (id),
  created_at  timestamptz NOT NULL
);
CREATE INDEX org_event_entity_idx ON org_event (entity_type, entity_id, created_at);
CREATE TRIGGER org_event_append_only BEFORE UPDATE OR DELETE ON org_event
  FOR EACH ROW EXECUTE FUNCTION append_only_violation();

ALTER TABLE card_event   ADD COLUMN copied_from_card_id char(26) REFERENCES card (id);
ALTER TABLE card_comment ADD COLUMN copied_from_card_id char(26) REFERENCES card (id);
CREATE INDEX card_event_copied_idx   ON card_event (copied_from_card_id)   WHERE copied_from_card_id IS NOT NULL;
CREATE INDEX card_comment_copied_idx ON card_comment (copied_from_card_id) WHERE copied_from_card_id IS NOT NULL;

GRANT SELECT, INSERT, UPDATE, DELETE ON team TO app_rw;
GRANT SELECT, INSERT, DELETE ON team_member TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON program TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON project TO app_rw;
GRANT SELECT, INSERT, DELETE ON card_link TO app_rw;
GRANT SELECT, INSERT ON org_event TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0004_org') ON CONFLICT DO NOTHING;

-- ===== 0005_tags =====
-- Admin-managed tag vocabulary (D-062, amends D-019). card.tags stays text[] of tag names; the
-- backend accepts only names present here. Backfilled from the tags already on cards.
CREATE TABLE tag (
  id          char(26)    PRIMARY KEY,
  name        text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 40),
  created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX tag_name_idx ON tag (lower(name));

-- Deterministic Crockford-safe id from the lower-cased name (hex digits only), one per distinct name.
INSERT INTO tag (id, name)
SELECT DISTINCT ON (lower(t)) upper(left(md5('tag:' || lower(t)), 26)), t
FROM card, unnest(tags) AS t
ORDER BY lower(t), t;

ALTER TABLE org_event DROP CONSTRAINT org_event_entity_type_check;
ALTER TABLE org_event ADD CONSTRAINT org_event_entity_type_check
  CHECK (entity_type IN ('team', 'program', 'project', 'tag'));

GRANT SELECT, INSERT, UPDATE, DELETE ON tag TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0005_tags') ON CONFLICT DO NOTHING;

-- ===== 0006_profile =====
-- Profile (D-064c): a person may override the synced display name and set their own picture.
-- name_override / photo_source tell the Entra sync (D-037) what it may overwrite:
--   name_override = false  -> sync may set name;  photo_source <> 'user' -> sync may set photo.
ALTER TABLE app_user
  ADD COLUMN name_override boolean NOT NULL DEFAULT false,
  ADD COLUMN photo         bytea,
  ADD COLUMN photo_type    text CHECK (photo_type IN ('image/jpeg', 'image/png', 'image/webp')),
  ADD COLUMN photo_source  text CHECK (photo_source IN ('user', 'synced')),
  ADD COLUMN photo_updated_at timestamptz,
  ADD CONSTRAINT app_user_photo_consistent CHECK (
    (photo IS NULL AND photo_type IS NULL AND photo_source IS NULL AND photo_updated_at IS NULL) OR
    (photo IS NOT NULL AND photo_type IS NOT NULL AND photo_source IS NOT NULL AND photo_updated_at IS NOT NULL)
  ),
  ADD CONSTRAINT app_user_photo_size CHECK (photo IS NULL OR octet_length(photo) <= 262144);

INSERT INTO schema_migration (id) VALUES ('0006_profile') ON CONFLICT DO NOTHING;

-- ===== 0007_s3a =====
-- S3a: inbox stamp (D-066), comment threads + votes (D-068), link attachments (D-069).
ALTER TABLE app_user ADD COLUMN inbox_seen_at timestamptz;
CREATE INDEX card_event_created_idx ON card_event (created_at);

ALTER TABLE card_comment ADD COLUMN parent_id char(26) REFERENCES card_comment (id);
CREATE INDEX card_comment_parent_idx ON card_comment (parent_id);

CREATE TABLE comment_vote (
  comment_id  char(26)    NOT NULL REFERENCES card_comment (id) ON DELETE CASCADE,
  user_id     char(26)    NOT NULL REFERENCES app_user (id),
  value       smallint    NOT NULL CHECK (value IN (-1, 1)),
  created_at  timestamptz NOT NULL,
  PRIMARY KEY (comment_id, user_id)
);

CREATE TABLE attachment (
  id          char(26)    PRIMARY KEY,
  card_id     char(26)    REFERENCES card (id),
  project_id  char(26)    REFERENCES project (id),
  title       text        NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200),
  url         text        NOT NULL CHECK (char_length(url) BETWEEN 1 AND 2048 AND url ~* '^https?://'),
  kind        text        CHECK (kind IN ('document', 'design', 'spec', 'other')),
  note        text        NOT NULL DEFAULT '' CHECK (char_length(note) <= 1000),
  added_by    char(26)    NOT NULL REFERENCES app_user (id),
  added_at    timestamptz NOT NULL,
  CHECK ((card_id IS NULL) <> (project_id IS NULL))
);
CREATE INDEX attachment_card_idx ON attachment (card_id);
CREATE INDEX attachment_project_idx ON attachment (project_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON comment_vote TO app_rw;
GRANT SELECT, INSERT, DELETE ON attachment TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0007_s3a') ON CONFLICT DO NOTHING;

-- ===== 0008_s3b =====
-- S3b: time entries (D-071), notification outbox + stub mail (D-073/D-074), email opt-in, Teams webhook (D-075).
CREATE TABLE time_entry (
  id          char(26)     PRIMARY KEY,
  card_id     char(26)     NOT NULL REFERENCES card (id),
  user_id     char(26)     NOT NULL REFERENCES app_user (id),
  date        date         NOT NULL,
  hours       numeric(6,2) NOT NULL CHECK (hours > 0 AND hours <= 24),
  note        text         NOT NULL DEFAULT '' CHECK (char_length(note) <= 500),
  created_at  timestamptz  NOT NULL,
  updated_at  timestamptz  NOT NULL
);
CREATE INDEX time_entry_card_idx ON time_entry (card_id, date);

CREATE TABLE notification (
  id          char(26)    PRIMARY KEY,
  channel     text        NOT NULL CHECK (channel IN ('email', 'teams')),
  target_id   char(26)    NOT NULL,
  kind        text        NOT NULL CHECK (kind IN ('assigned', 'blocked', 'comment', 'closed')),
  payload     jsonb       NOT NULL,
  created_at  timestamptz NOT NULL,
  sent_at     timestamptz,
  attempts    smallint    NOT NULL DEFAULT 0,
  last_error  text
);
CREATE INDEX notification_pending_idx ON notification (created_at) WHERE sent_at IS NULL;

CREATE TABLE mail_stub_message (
  id          char(26)    PRIMARY KEY,
  to_email    text        NOT NULL,
  subject     text        NOT NULL,
  body        text        NOT NULL,
  created_at  timestamptz NOT NULL
);

ALTER TABLE user_preference ADD COLUMN notify_email boolean NOT NULL DEFAULT false;
ALTER TABLE team ADD COLUMN teams_webhook_url_enc bytea;

GRANT SELECT, INSERT, UPDATE, DELETE ON time_entry TO app_rw;
GRANT SELECT, INSERT, UPDATE ON notification TO app_rw;
GRANT SELECT, INSERT, DELETE ON mail_stub_message TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0008_s3b') ON CONFLICT DO NOTHING;

-- ===== 0009_defaults =====
-- D-077: personal defaults for the Org tab.
ALTER TABLE user_preference
  ADD COLUMN primary_team_id    char(26) REFERENCES team (id) ON DELETE SET NULL,
  ADD COLUMN primary_project_id char(26) REFERENCES project (id) ON DELETE SET NULL,
  ADD COLUMN org_order          text NOT NULL DEFAULT 'team_first' CHECK (org_order IN ('team_first', 'project_first'));

INSERT INTO schema_migration (id) VALUES ('0009_defaults') ON CONFLICT DO NOTHING;

-- ===== 0010_admission =====
-- D-083: admission gate. Users are invited by an admin; sign-in requires an invited/active row.
ALTER TABLE app_user DROP CONSTRAINT app_user_status_check;
ALTER TABLE app_user ADD CONSTRAINT app_user_status_check CHECK (status IN ('invited', 'active', 'inactive'));
ALTER TABLE app_user
  ADD COLUMN invited_at timestamptz,
  ADD COLUMN invited_by char(26) REFERENCES app_user (id);
ALTER TABLE notification DROP CONSTRAINT notification_kind_check;
ALTER TABLE notification ADD CONSTRAINT notification_kind_check CHECK (kind IN ('assigned', 'blocked', 'comment', 'closed', 'invited'));

INSERT INTO schema_migration (id) VALUES ('0010_admission') ON CONFLICT DO NOTHING;

-- ===== 0011_leads =====
-- CR-11: team lead. A per-team flag set by an admin; a lead manages that team's membership,
-- projects and Teams webhook, and nothing outside their own teams.
ALTER TABLE team_member ADD COLUMN is_lead boolean NOT NULL DEFAULT false;
-- team_member only ever gained rows before; the lead flag is the first UPDATE on it.
GRANT UPDATE ON team_member TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0011_leads') ON CONFLICT DO NOTHING;

-- ===== 0012_project_close =====
-- CR-12: retiring a project in two steps. `accepting = false` stops intake (no card created in or
-- moved into the project) while the cards already there run to completion; `closed_at` retires it
-- and hides it from lists and pickers. Both are admin-only; closure refuses while open cards remain.
ALTER TABLE project
  ADD COLUMN accepting  boolean NOT NULL DEFAULT true,
  ADD COLUMN closed_at  timestamptz,
  ADD COLUMN closed_by  char(26) REFERENCES app_user (id);
-- Every project picker and filter reads the open set; closed projects are the rare tail.
CREATE INDEX project_open_idx ON project (team_id) WHERE closed_at IS NULL;

INSERT INTO schema_migration (id) VALUES ('0012_project_close') ON CONFLICT DO NOTHING;

-- ===== 0013_inbox =====
-- CR-19: inbox housekeeping. Nothing is ever deleted - the card history is append-only (FR-041);
-- all three parts are filters or flags over the query `cards/inbox.ts` already runs.
-- 1. Retention becomes a per-person setting instead of the hard-coded WINDOW_DAYS = 30.
ALTER TABLE user_preference
  ADD COLUMN inbox_window_days integer NOT NULL DEFAULT 30
    CHECK (inbox_window_days BETWEEN 1 AND 365);
-- 2. "Clear everything up to this date" for one person: a second stamp beside inbox_seen_at.
ALTER TABLE app_user ADD COLUMN inbox_cleared_before timestamptz;
-- 3. Per-entry read state. inbox_seen_at stays as the "mark all seen" high-water mark; an entry
-- is unread when it is newer than that stamp AND has no row here. Rows age out with the window.
CREATE TABLE inbox_read (
  user_id   char(26)    NOT NULL REFERENCES app_user (id) ON DELETE CASCADE,
  event_id  char(26)    NOT NULL REFERENCES card_event (id) ON DELETE CASCADE,
  read_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, event_id)
);
GRANT SELECT, INSERT, DELETE ON inbox_read TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0013_inbox') ON CONFLICT DO NOTHING;

-- ===== 0014_remove_uat =====
-- 0014: UAT is no longer a card state (D-112, user 2026-10-07). Cards in UAT move to Testing, each
-- with a `state` event (FR-041) attributed to the card's owner - a migration has no actor of its
-- own - then the state rule narrows. Ids are derived from the card id, as 0005's backfill does.
INSERT INTO card_event (id, card_id, group_id, field, old_value, new_value, actor_id, created_at)
SELECT upper(left(md5('uat-event:' || id), 26)), id, upper(left(md5('uat-group:' || id), 26)),
       'state', '"uat"'::jsonb, '"testing"'::jsonb, owner_id, now()
  FROM card
 WHERE state = 'uat';

UPDATE card SET state = 'testing', version = version + 1, updated_at = now() WHERE state = 'uat';

ALTER TABLE card DROP CONSTRAINT card_state_check;
ALTER TABLE card ADD CONSTRAINT card_state_check
  CHECK (state IN ('backlog', 'in_prep', 'ready', 'in_development', 'testing', 'delivered', 'cancelled'));

INSERT INTO schema_migration (id) VALUES ('0014_remove_uat') ON CONFLICT DO NOTHING;

-- ===== 0015_time_log =====
-- D-116 time log: a week note and leave/holiday days per person, a once-per-week record of the
-- Friday and Monday mail runs, and the four time-mail kinds in the outbox.
CREATE TABLE time_week_note (
  user_id     char(26)    NOT NULL REFERENCES app_user (id),
  week_start  date        NOT NULL CHECK (extract(isodow FROM week_start) = 1),
  note        text        NOT NULL CHECK (char_length(note) <= 2000),
  updated_at  timestamptz NOT NULL,
  PRIMARY KEY (user_id, week_start)
);

CREATE TABLE time_day_off (
  user_id     char(26)    NOT NULL REFERENCES app_user (id),
  date        date        NOT NULL CHECK (extract(isodow FROM date) BETWEEN 1 AND 5),
  kind        text        NOT NULL CHECK (kind IN ('leave', 'holiday')),
  created_at  timestamptz NOT NULL,
  PRIMARY KEY (user_id, date)
);

CREATE TABLE time_mail_run (
  job         text        NOT NULL CHECK (job IN ('friday_reminder', 'monday_review')),
  week_start  date        NOT NULL,
  ran_at      timestamptz NOT NULL,
  PRIMARY KEY (job, week_start)
);

CREATE INDEX time_entry_user_date_idx ON time_entry (user_id, date);

ALTER TABLE notification DROP CONSTRAINT notification_kind_check;
ALTER TABLE notification ADD CONSTRAINT notification_kind_check CHECK (kind IN (
  'assigned', 'blocked', 'comment', 'closed', 'invited',
  'time_reminder', 'time_shortfall', 'time_shortfall_lead', 'time_team_report'));

GRANT SELECT, INSERT, UPDATE, DELETE ON time_week_note TO app_rw;
GRANT SELECT, INSERT, UPDATE, DELETE ON time_day_off TO app_rw;
GRANT SELECT, INSERT ON time_mail_run TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0015_time_log') ON CONFLICT DO NOTHING;

-- ===== 0016_contact_admin =====
-- D-125: a person who cannot sign in can message the admins; the message goes out as email.
ALTER TABLE notification DROP CONSTRAINT notification_kind_check;
ALTER TABLE notification ADD CONSTRAINT notification_kind_check CHECK (kind IN (
  'assigned', 'blocked', 'comment', 'closed', 'invited',
  'time_reminder', 'time_shortfall', 'time_shortfall_lead', 'time_team_report',
  'contact_admin'));

INSERT INTO schema_migration (id) VALUES ('0016_contact_admin') ON CONFLICT DO NOTHING;

-- ===== 0017_priority_optional =====
-- D-134: a card may have no priority (the new default). Existing cards keep theirs.
ALTER TABLE card ALTER COLUMN priority DROP DEFAULT;
ALTER TABLE card ALTER COLUMN priority DROP NOT NULL;

INSERT INTO schema_migration (id) VALUES ('0017_priority_optional') ON CONFLICT DO NOTHING;

-- ===== 0018_mail_templates =====
-- D-141: admins edit the subject and text of each email; an email with no row here keeps the
-- built-in wording. One row per email kind.
CREATE TABLE mail_template (
  kind        text        PRIMARY KEY CHECK (kind IN (
                'invited', 'assigned', 'blocked', 'comment', 'closed',
                'time_reminder', 'time_shortfall', 'time_shortfall_lead', 'time_team_report',
                'contact_admin')),
  subject     text        NOT NULL CHECK (char_length(subject) BETWEEN 1 AND 300),
  body        text        NOT NULL CHECK (char_length(body) BETWEEN 1 AND 10000),
  updated_at  timestamptz NOT NULL,
  updated_by  char(26)    NOT NULL REFERENCES app_user (id)
);

GRANT SELECT, INSERT, UPDATE, DELETE ON mail_template TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0018_mail_templates') ON CONFLICT DO NOTHING;

-- ===== 0019_login_issues =====
-- D-144: messages from people who cannot sign in (D-125) are kept for Administration > Login
-- issues, newest first; an admin marks one resolved. The emails to admins go on as before.
CREATE TABLE login_issue (
  id           char(26)    PRIMARY KEY,
  name         text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120),
  email        text        NOT NULL CHECK (char_length(email) BETWEEN 3 AND 254),
  message      text        NOT NULL CHECK (char_length(message) BETWEEN 1 AND 2000),
  created_at   timestamptz NOT NULL,
  resolved_at  timestamptz,
  resolved_by  char(26)    REFERENCES app_user (id),
  CHECK ((resolved_at IS NULL) = (resolved_by IS NULL))
);
CREATE INDEX login_issue_created_idx ON login_issue (created_at DESC);

GRANT SELECT, INSERT, UPDATE ON login_issue TO app_rw;

INSERT INTO schema_migration (id) VALUES ('0019_login_issues') ON CONFLICT DO NOTHING;

-- ===== 0020_testing_to_uat =====
-- 0020: the Testing state is renamed UAT (user 2026-10-22). Cards in Testing move to UAT, each
-- with a `state` event (FR-041) attributed to the card's owner - a migration has no actor of its
-- own, as in 0014. Old events keep the value they recorded. Ids are derived from the card id.
ALTER TABLE card DROP CONSTRAINT card_state_check;

INSERT INTO card_event (id, card_id, group_id, field, old_value, new_value, actor_id, created_at)
SELECT upper(left(md5('uat2-event:' || id), 26)), id, upper(left(md5('uat2-group:' || id), 26)),
       'state', '"testing"'::jsonb, '"uat"'::jsonb, owner_id, now()
  FROM card
 WHERE state = 'testing';

UPDATE card SET state = 'uat', version = version + 1, updated_at = now() WHERE state = 'testing';

ALTER TABLE card ADD CONSTRAINT card_state_check
  CHECK (state IN ('backlog', 'in_prep', 'ready', 'in_development', 'uat', 'delivered', 'cancelled'));

INSERT INTO schema_migration (id) VALUES ('0020_testing_to_uat') ON CONFLICT DO NOTHING;

COMMIT;
